import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/hocket_editor.BpN4J_3P.svg",k=JSON.parse('{"title":"Hocket","description":"","frontmatter":{},"headers":[],"relativePath":"generators/HOCKET.md","filePath":"generators/HOCKET.md"}'),n={name:"generators/HOCKET.md"};function h(i,t,c,d,l,u){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="hocket" tabindex="-1">Hocket <a class="header-anchor" href="#hocket" aria-label="Permalink to &quot;Hocket&quot;">​</a></h1><p><img src="'+r+'" alt="A hocket&#39;s settings, naming its source track"></p><p>A Hocket shares one track&#39;s notes out among other tracks, one note each, as a hocket in early music passes a melody between singers. Its Source Track names the track whose notes it shares.</p><h2 id="turn-order" tabindex="-1">Turn Order <a class="header-anchor" href="#turn-order" aria-label="Permalink to &quot;Turn Order&quot;">​</a></h2><p>Add the Hocket to a chain on the clips that should take turns. In each scene, the tracks whose clips run it take turns at the source&#39;s notes, left to right in the song&#39;s track order, and round again: with one such track it plays every note, with four each plays every fourth. A rest passes no turn, and a chord passes whole to one track. The notes handed out are the source&#39;s notes as they come out of the source clip&#39;s chain. Each keeps the source&#39;s pitch, timing, length and velocity, and then moves with the hocketing track&#39;s groove, Rush and Drag as the track&#39;s own notes do, but not with the track&#39;s Transpose or the generators after the Hocket in its chain, so that the melody stays whole.</p><p>The source track plays its own pattern as ever, with nothing of the Hocket applied to it, so turn its Mute on in the track editor to hear only the hocket; a muted source still hands out its notes. A hocketing track also plays its own pattern&#39;s notes, besides those it is handed, so a pattern of rests plays only the hocket. The usual use is four tracks on four patches of one synth, or four instances of a monosynth with slightly different settings in the DAW, trading a lead line so that no one sound plays every note.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames it, and every chain using it follows.</td></tr><tr><td>Source track</td><td>The track whose notes it shares, a track of the current song. Renaming the track renames this too, and a track the song doesn&#39;t have hands out nothing.</td></tr><tr><td>Restart</td><td>&quot;every clip&quot;, the default, starts the turns again with the first track at each clip the source plays; &quot;on new scene&quot; and &quot;whole song&quot; carry them on.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p><a href="./../CONCEPTS#hocketing">Concepts</a> walks through it. <code>examples/learning/19_hocket_shanty.yml</code> shows it on The Wellerman, with four voices.</p>',10)])])}const g=e(n,[["render",h]]);export{k as __pageData,g as default};
